1	const MODES = {
2	  FOCUS: 'focus',
3	  SHORT: 'short',
4	  LONG: 'long',
5	};
6	
7	const RING_LEN = 2 * Math.PI * 88;
8	
9	const els = {
10	  modeLabel: document.getElementById('modeLabel'),
11	  timeDisplay: document.getElementById('timeDisplay'),
12	  phaseHint: document.getElementById('phaseHint'),
13	  ringProgress: document.getElementById('ringProgress'),
14	  btnPrimary: document.getElementById('btnPrimary'),
15	  btnReset: document.getElementById('btnReset'),
16	  btnSkip: document.getElementById('btnSkip'),
17	  chkAlwaysOnTop: document.getElementById('chkAlwaysOnTop'),
18	  statToday: document.getElementById('statToday'),
19	  statCycle: document.getElementById('statCycle'),
20	  btnSettings: document.getElementById('btnSettings'),
21	  dlgSettings: document.getElementById('dlgSettings'),
22	  setWork: document.getElementById('setWork'),
23	  setShort: document.getElementById('setShort'),
24	  setLong: document.getElementById('setLong'),
25	  btnCancelSettings: document.getElementById('btnCancelSettings'),
26	  setRingtone: document.getElementById('setRingtone'),
27	  setAutoStart: document.getElementById('setAutoStart'),
28	  stickyNote: document.getElementById('stickyNote'),
29	  breakOverlay: document.getElementById('breakOverlay'),
30	};
31	
32	const STORAGE_KEYS = {
33	  work: 'pomodoro_work_min',
34	  short: 'pomodoro_short_min',
35	  long: 'pomodoro_long_min',
36	  today: 'pomodoro_today_count',
37	  todayDate: 'pomodoro_today_date',
38	  slot: 'pomodoro_block_slot',
39	  alwaysOnTop: 'pomodoro_always_on_top',
40	  ringtone: 'pomodoro_ringtone',
41	  autoStart: 'pomodoro_auto_start',
42	  stickyNote: 'pomodoro_sticky_note',
43	};
44	
45	const RINGTONES = {
46	  classic: { hi: 932, lo: 698.46, type: 'square' },
47	  bell: { hi: 1174.66, lo: 880, type: 'sine' },
48	  chime: { hi: 1318.5, lo: 1046.5, type: 'triangle' },
49	  digital: { hi: 1760, lo: 1174.66, type: 'sawtooth' },
50	};
51	
52	function loadSettings() {
53	  const w = Number(localStorage.getItem(STORAGE_KEYS.work)) || 25;
54	  const s = Number(localStorage.getItem(STORAGE_KEYS.short)) || 5;
55	  const l = Number(localStorage.getItem(STORAGE_KEYS.long)) || 15;
56	  const ringtone = localStorage.getItem(STORAGE_KEYS.ringtone) || 'classic';
57	  const autoStart = localStorage.getItem(STORAGE_KEYS.autoStart) === '1';
58	  return {
59	    workMin: Math.min(120, Math.max(1, w)),
60	    shortMin: Math.min(60, Math.max(1, s)),
61	    longMin: Math.min(60, Math.max(1, l)),
62	    ringtone: RINGTONES[ringtone] ? ringtone : 'classic',
63	    autoStart,
64	  };
65	}
66	
67	function saveSettings(workMin, shortMin, longMin, ringtone, autoStart) {
68	  localStorage.setItem(STORAGE_KEYS.work, String(workMin));
69	  localStorage.setItem(STORAGE_KEYS.short, String(shortMin));
70	  localStorage.setItem(STORAGE_KEYS.long, String(longMin));
71	  localStorage.setItem(STORAGE_KEYS.ringtone, ringtone);
72	  localStorage.setItem(STORAGE_KEYS.autoStart, autoStart ? '1' : '0');
73	}
74	
75	function todayKey() {
76	  const d = new Date();
77	  return `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}`;
78	}
79	
80	function loadTodayCount() {
81	  const key = localStorage.getItem(STORAGE_KEYS.todayDate);
82	  if (key !== todayKey()) {
83	    localStorage.setItem(STORAGE_KEYS.todayDate, todayKey());
84	    localStorage.setItem(STORAGE_KEYS.today, '0');
85	    return 0;
86	  }
87	  return Number(localStorage.getItem(STORAGE_KEYS.today)) || 0;
88	}
89	
90	function bumpTodayCount() {
91	  const n = loadTodayCount() + 1;
92	  localStorage.setItem(STORAGE_KEYS.todayDate, todayKey());
93	  localStorage.setItem(STORAGE_KEYS.today, String(n));
94	  return n;
95	}
96	
97	function loadSlot() {
98	  return Math.min(3, Math.max(0, Number(localStorage.getItem(STORAGE_KEYS.slot)) || 0));
99	}
100	
101	function saveSlot(i) {
102	  localStorage.setItem(STORAGE_KEYS.slot, String(i));
103	}
104	
105	let settings = loadSettings();
106	let mode = MODES.FOCUS;
107	let totalSeconds = settings.workMin * 60;
108	let remaining = totalSeconds;
109	let running = false;
110	let timerId = null;
111	let slot = loadSlot();
112	
113	function modeLabelText() {
114	  if (mode === MODES.FOCUS) return '专注';
115	  if (mode === MODES.SHORT) return '短休息';
116	  return '长休息';
117	}
118	
119	function updateModeClass() {
120	  els.modeLabel.textContent = modeLabelText();
121	  els.modeLabel.classList.remove('short', 'long');
122	  els.ringProgress.classList.remove('short', 'long');
123	  if (mode === MODES.SHORT) {
124	    els.modeLabel.classList.add('short');
125	    els.ringProgress.classList.add('short');
126	  } else if (mode === MODES.LONG) {
127	    els.modeLabel.classList.add('long');
128	    els.ringProgress.classList.add('long');
129	  }
130	}
131	
132	function formatTime(sec) {
133	  const m = Math.floor(sec / 60);
134	  const s = sec % 60;
135	  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
136	}
137	
138	function setRingProgress() {
139	  const p = totalSeconds > 0 ? remaining / totalSeconds : 0;
140	  els.ringProgress.style.strokeDashoffset = String(RING_LEN * (1 - p));
141	}
142	
143	function updateDockBadge() {
144	  if (!window.pomodoro?.setDockBadge) return;
145	  if (running) {
146	    window.pomodoro.setDockBadge(formatTime(remaining));
147	  } else {
148	    window.pomodoro.setDockBadge('');
149	  }
150	}
151	
152	function cycleLabel() {
153	  if (mode === MODES.LONG) {
154	    return '1';
155	  }
156	  return `${slot + 1}`;
157	}
158	
159	function render() {
160	  els.timeDisplay.textContent = formatTime(remaining);
161	  updateModeClass();
162	  setRingProgress();
163	  els.statToday.textContent = String(loadTodayCount());
164	  els.statCycle.textContent = cycleLabel();
165	  els.btnPrimary.textContent = running ? '暂停' : remaining === totalSeconds ? '开始' : '继续';
166	  if (running) {
167	    els.phaseHint.textContent = mode === MODES.FOCUS ? '保持专注' : '放松一下';
168	  } else if (mode === MODES.LONG) {
169	    els.phaseHint.textContent = '长休之后将开始新一轮';
170	  } else if (mode === MODES.SHORT) {
171	    els.phaseHint.textContent = '准备进入下一段专注';
172	  } else {
173	    els.phaseHint.textContent = '准备开始';
174	  }
175	  updateDockBadge();
176	}
177	
178	function playAlarmRing() {
179	  try {
180	    const Ctx = window.AudioContext || window.webkitAudioContext;
181	    if (!Ctx) return;
182	    const ctx = new Ctx();
183	    ctx.resume().catch(() => {});
184	
185	    const master = ctx.createGain();
186	    master.gain.value = 0.16;
187	    master.connect(ctx.destination);
188	
189	    const tone = RINGTONES[settings.ringtone] || RINGTONES.classic;
190	    const hi = tone.hi;
191	    const lo = tone.lo;
192	    const waveType = tone.type;
193	
194	    function scheduleBeep(start, freq) {
195	      const dur = 0.11;
196	      const o = ctx.createOscillator();
197	      const g = ctx.createGain();
198	      o.type = waveType;
199	      o.frequency.value = freq;
200	      g.gain.setValueAtTime(0.0001, start);
201	      g.gain.exponentialRampToValueAtTime(0.32, start + 0.01);
202	      g.gain.exponentialRampToValueAtTime(0.0001, start + dur);
203	      o.connect(g);
204	      g.connect(master);
205	      o.start(start);
206	      o.stop(start + dur + 0.02);
207	    }
208	
209	    let t = ctx.currentTime + 0.05;
210	    const groups = 6;
211	    for (let g = 0; g < groups; g += 1) {
212	      scheduleBeep(t, hi);
213	      t += 0.19;
214	      scheduleBeep(t, lo);
215	      t += 0.19;
216	      scheduleBeep(t, hi);
217	      t += 0.19;
218	      t += 0.36;
219	    }
220	
221	    const stopAt = (t - ctx.currentTime + 0.4) * 1000;
222	    setTimeout(() => {
223	      ctx.close().catch(() => {});
224	    }, Math.max(0, stopAt));
225	  } catch {
226	    /* ignore */
227	  }
228	}
229	
230	async function notify(title, body) {
231	  if (window.pomodoro?.notify) {
232	    await window.pomodoro.notify(title, body);
233	  }
234	}
235	
236	function applyModeDurations() {
237	  if (mode === MODES.FOCUS) totalSeconds = settings.workMin * 60;
238	  else if (mode === MODES.SHORT) totalSeconds = settings.shortMin * 60;
239	  else totalSeconds = settings.longMin * 60;
240	  remaining = totalSeconds;
241	}
242	
243	function afterFocusCompleted() {
244	  if (slot >= 3) {
245	    mode = MODES.LONG;
246	    slot = 0;
247	    saveSlot(0);
248	  } else {
249	    mode = MODES.SHORT;
250	    slot += 1;
251	    saveSlot(slot);
252	  }
253	}
254	
255	function goToFocusFromBreak() {
256	  mode = MODES.FOCUS;
257	}
258	
259	let autoStartTimeout = null;
260	
261	function onTimerComplete() {
262	  running = false;
263	  clearInterval(timerId);
264	  timerId = null;
265	  playAlarmRing();
266	
267	  if (mode === MODES.FOCUS) {
268	    bumpTodayCount();
269	    notify('专注结束', '休息一会儿吧。');
270	    afterFocusCompleted();
271	    showBreakOverlay();
272	  } else {
273	    notify('休息结束', '开始下一个番茄。');
274	    goToFocusFromBreak();
275	  }
276	  applyModeDurations();
277	  remaining = totalSeconds;
278	  render();
279	
280	  if (settings.autoStart) {
281	    if (autoStartTimeout) clearTimeout(autoStartTimeout);
282	    autoStartTimeout = setTimeout(() => {
283	      autoStartTimeout = null;
284	      if (!running) startTimer();
285	    }, 3000);
286	  }
287	}
288	
289	function tick() {
290	  remaining -= 1;
291	  if (remaining <= 0) {
292	    remaining = 0;
293	    onTimerComplete();
294	    return;
295	  }
296	  render();
297	}
298	
299	function cancelAutoStart() {
300	  if (autoStartTimeout) {
301	    clearTimeout(autoStartTimeout);
302	    autoStartTimeout = null;
303	  }
304	}
305	
306	function startTimer() {
307	  cancelAutoStart();
308	  if (timerId) clearInterval(timerId);
309	  running = true;
310	  timerId = setInterval(tick, 1000);
311	  render();
312	}
313	
314	function pauseTimer() {
315	  cancelAutoStart();
316	  running = false;
317	  if (timerId) clearInterval(timerId);
318	  timerId = null;
319	  render();
320	}
321	
322	function resetPhase() {
323	  pauseTimer();
324	  applyModeDurations();
325	  remaining = totalSeconds;
326	  render();
327	}
328	
329	function skipPhase() {
330	  pauseTimer();
331	  if (mode === MODES.FOCUS) {
332	    if (slot >= 3) {
333	      mode = MODES.LONG;
334	      slot = 0;
335	      saveSlot(0);
336	    } else {
337	      mode = MODES.SHORT;
338	    }
339	  } else {
340	    goToFocusFromBreak();
341	  }
342	  applyModeDurations();
343	  remaining = totalSeconds;
344	  render();
345	}
346	
347	function showBreakOverlay() {
348	  if (mode === MODES.FOCUS) return;
349	  els.breakOverlay.classList.remove('hidden');
350	  const dismiss = () => {
351	    els.breakOverlay.classList.add('hidden');
352	    els.breakOverlay.removeEventListener('click', dismiss);
353	  };
354	  els.breakOverlay.addEventListener('click', dismiss);
355	  setTimeout(dismiss, 4000);
356	}
357	
358	els.stickyNote.value = localStorage.getItem(STORAGE_KEYS.stickyNote) || '';
359	els.stickyNote.addEventListener('input', () => {
360	  localStorage.setItem(STORAGE_KEYS.stickyNote, els.stickyNote.value);
361	});
362	
363	els.btnPrimary.addEventListener('click', () => {
364	  if (running) pauseTimer();
365	  else startTimer();
366	});
367	
368	els.btnReset.addEventListener('click', () => {
369	  resetPhase();
370	});
371	
372	els.btnSkip.addEventListener('click', () => {
373	  skipPhase();
374	});
375	
376	els.chkAlwaysOnTop.addEventListener('change', () => {
377	  const on = els.chkAlwaysOnTop.checked;
378	  localStorage.setItem(STORAGE_KEYS.alwaysOnTop, on ? '1' : '0');
379	  if (window.pomodoro?.setAlwaysOnTop) {
380	    window.pomodoro.setAlwaysOnTop(on);
381	  }
382	});
383	
384	els.btnSettings.addEventListener('click', () => {
385	  els.setWork.value = String(settings.workMin);
386	  els.setShort.value = String(settings.shortMin);
387	  els.setLong.value = String(settings.longMin);
388	  els.setRingtone.value = settings.ringtone;
389	  els.setAutoStart.checked = settings.autoStart;
390	  els.dlgSettings.showModal();
391	});
392	
393	els.btnCancelSettings.addEventListener('click', () => {
394	  els.dlgSettings.returnValue = '';
395	  els.dlgSettings.close();
396	});
397	
398	els.dlgSettings.addEventListener('close', () => {
399	  if (els.dlgSettings.returnValue !== 'save') return;
400	  const w = Number(els.setWork.value);
401	  const s = Number(els.setShort.value);
402	  const l = Number(els.setLong.value);
403	  if (![w, s, l].every((n) => Number.isFinite(n) && n > 0)) return;
404	  const ringtone = els.setRingtone.value;
405	  const autoStart = els.setAutoStart.checked;
406	  settings = {
407	    workMin: Math.min(120, Math.max(1, Math.round(w))),
408	    shortMin: Math.min(60, Math.max(1, Math.round(s))),
409	    longMin: Math.min(60, Math.max(1, Math.round(l))),
410	    ringtone: RINGTONES[ringtone] ? ringtone : 'classic',
411	    autoStart,
412	  };
413	  saveSettings(settings.workMin, settings.shortMin, settings.longMin, settings.ringtone, settings.autoStart);
414	  pauseTimer();
415	  applyModeDurations();
416	  remaining = totalSeconds;
417	  render();
418	});
419	
420	(function init() {
421	  applyModeDurations();
422	  remaining = totalSeconds;
423	  els.ringProgress.style.strokeDasharray = String(RING_LEN);
424	  const aot = localStorage.getItem(STORAGE_KEYS.alwaysOnTop) === '1';
425	  els.chkAlwaysOnTop.checked = aot;
426	  if (window.pomodoro?.setAlwaysOnTop) {
427	    window.pomodoro.setAlwaysOnTop(aot);
428	  }
429	  slot = loadSlot();
430	  render();
431	})();
